package com.ferreteriahuaman.service;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.ferreteriahuaman.security.AuthFailure;
import java.net.http.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
class DecolectaServiceTest {
 @Test void rejectsInvalidRucBeforeNetwork(){var client=mock(HttpClient.class);var s=new DecolectaService("private-test-key",new ObjectMapper(),client);assertThatThrownBy(()->s.lookup("00000000000")).isInstanceOf(AuthFailure.class);verifyNoInteractions(client);}
 @Test void missingKeyAllowsManualFallback(){var s=new DecolectaService("",new ObjectMapper(),mock(HttpClient.class));assertThatThrownBy(()->s.lookup("20601030013")).isInstanceOfSatisfying(AuthFailure.class,e->assertThat(e.status()).isEqualTo(503));}
 @Test @SuppressWarnings("unchecked") void mapsAndCachesSuccessfulResponse() throws Exception {
 var client=mock(HttpClient.class);HttpResponse<String> response=mock(HttpResponse.class);when(response.statusCode()).thenReturn(200);when(response.body()).thenReturn("{\"numero_documento\":\"20601030013\",\"razon_social\":\"Empresa Consultada\",\"estado\":\"ACTIVO\",\"condicion\":\"HABIDO\",\"ubigeo\":\"150131\"}");when(client.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenReturn(response);
 var s=new DecolectaService("private-test-key",new ObjectMapper(),client);var result=s.lookup("20601030013");assertThat(result.razonSocial()).isEqualTo("Empresa Consultada");assertThat(result.condicion()).isEqualTo("HABIDO");assertThat(s.lookup("20601030013")).isSameAs(result);verify(client,times(1)).send(argThat(request->request.uri().getScheme().equals("https")&&!request.uri().toString().contains("private-test-key")&&request.headers().firstValue("Authorization").orElse("").equals("Bearer private-test-key")),any(HttpResponse.BodyHandler.class));
 }
 @Test @SuppressWarnings("unchecked") void quotaErrorsAreSafe() throws Exception {var client=mock(HttpClient.class);HttpResponse<String> response=mock(HttpResponse.class);when(response.statusCode()).thenReturn(429);when(client.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenReturn(response);var s=new DecolectaService("private-test-key",new ObjectMapper(),client);assertThatThrownBy(()->s.lookup("20601030013")).isInstanceOfSatisfying(AuthFailure.class,e->{assertThat(e.status()).isEqualTo(429);assertThat(e.getMessage()).doesNotContain("private-test-key");});}
 @Test @SuppressWarnings("unchecked") void rejectsMismatchedDocument() throws Exception {var client=mock(HttpClient.class);HttpResponse<String> response=mock(HttpResponse.class);when(response.statusCode()).thenReturn(200);when(response.body()).thenReturn("{\"numero_documento\":\"20100000000\",\"razon_social\":\"Otra empresa\"}");when(client.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenReturn(response);var s=new DecolectaService("private-test-key",new ObjectMapper(),client);assertThatThrownBy(()->s.lookup("20601030013")).isInstanceOfSatisfying(AuthFailure.class,e->assertThat(e.status()).isEqualTo(503));}
 @Test @SuppressWarnings("unchecked") void dniUsesReniecAndCachesVerifiedIdentity()throws Exception{var client=mock(HttpClient.class);HttpResponse<String> response=mock(HttpResponse.class);when(response.statusCode()).thenReturn(200);when(response.body()).thenReturn("{\"document_number\":\"87654321\",\"full_name\":\"Persona consultada\"}");when(client.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenReturn(response);var service=new DecolectaService("private-test-key",new ObjectMapper(),client);assertThat(service.lookupDni("87654321").nombre()).isEqualTo("Persona consultada");service.lookupDni("87654321");verify(client,times(1)).send(argThat(r->r.uri().getPath().equals("/v1/reniec/dni")&&r.headers().firstValue("Authorization").orElse("").equals("Bearer private-test-key")),any(HttpResponse.BodyHandler.class));}
 @Test @SuppressWarnings("unchecked") void dniRejectsMismatchedIdentity()throws Exception{var client=mock(HttpClient.class);HttpResponse<String> response=mock(HttpResponse.class);when(response.statusCode()).thenReturn(200);when(response.body()).thenReturn("{\"document_number\":\"11111111\",\"full_name\":\"Otra persona\"}");when(client.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenReturn(response);var service=new DecolectaService("private-test-key",new ObjectMapper(),client);assertThatThrownBy(()->service.lookupDni("87654321")).isInstanceOf(AuthFailure.class);}
}
